def score(program: str) -> float:
    try:
        import ast
        nodes = ast.walk(ast.parse(program))
        count = sum(1 for n in nodes if isinstance(n, (ast.FunctionDef, ast.For, ast.While, ast.If, ast.Return)))
        return min(1.0, count / 20.0)
    except:
        return 0.0

